const icon=(k,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.box}"/></svg>`;
const money=n=>`${Number(n||0).toLocaleString(state.lang==='ru'?'ru-RU':'uk-UA')} грн`;
const request=async(path,method='GET',data)=>{const headers={'X-Init':tg.initData||''};let body;if(data instanceof FormData)body=data;else if(data!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(data)}const r=await fetch('/api/market'+path,{method,headers,body,cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(j.error||t('error')),{code:j.code});return j};
const items=r=>Array.isArray(r)?r:(r.items||[]),item=r=>r.item||r;
const when=s=>{if(!s)return '';const raw=String(s).replace(' ','T'),d=new Date(/(?:Z|[+-]\d{2}:?\d{2})$/.test(raw)?raw:raw+'Z');return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat(state.lang==='ru'?'ru-RU':'uk-UA',{day:'numeric',month:'short',year:'numeric'}).format(d)};
const onError=e=>toast(e.message||t('error'),3500);
function applyTheme(){const dark=state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.lang=state.lang;try{tg.setHeaderColor(dark?'#191b1f':'#ffffff');tg.setBackgroundColor(dark?'#191b1f':'#ffffff')}catch(e){}}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')applyTheme()});
ls.set('dm_intro','1');
const header=document.createElement('header');header.className='dm-header';document.body.insertBefore(header,$('#view'));
function drawHeader(){header.innerHTML=`<div class="dm-brandrow"><a class="dm-brand" href="#" data-dm="home" aria-label="Domivka">${icon('home')}<span>domivka</span></a><div class="row"><button class="dm-ib" data-dm="add" aria-label="${t('add')}">${icon('plus')}</button><button class="dm-ib" data-dm="settings" aria-label="${t('settings')}">${icon('settings')}</button></div></div><div class="dm-service" role="tablist" aria-label="${t('realty')} / ${t('market')}"><button role="tab" aria-selected="${state.service==='rental'}" class="${state.service==='rental'?'on':''}" data-service="rental">${icon('home')}${t('realty')}</button><button role="tab" aria-selected="${state.service==='market'}" class="${state.service==='market'?'on':''}" data-service="market">${icon('bag')}${t('market')}</button></div>`}
const rentalGo=go,rentalTabs=drawTabs,rentalHero=drawHero;
drawTabs=function(){if(state.service==='market'){const tabs=[['search','search',t('search')],['fav','heart',t('favorites')],['chats','chat',t('chats')],['orders','bag',t('orders')],['me','user',t('profile')]];$('#tabs').innerHTML=tabs.map(([k,i,l])=>`<button data-mtab="${k}" class="${state.tab===k?'on':''}"><b>${icon(i)}</b>${l}</button>`).join('');return}rentalTabs();const map={search:['search','search'],fav:['heart','favorites'],chats:['chat','chats'],trips:['bag','bookings'],me:['user','profile']};$('#tabs').querySelectorAll('button').forEach(b=>{const a=map[b.dataset.tab];if(a)b.innerHTML=`<b>${icon(a[0])}</b>${t(a[1])}`})};
drawHero=function(){const h=$('#hero');if(!h)return;if(TAB!=='search'||F.q||nF()||F.max||F.month){h.innerHTML='';return}h.innerHTML=`<div class="hero"><h1 class="h1">${t('rentalTitle').replace('\n','<br>')}</h1><p class="mut">${t('rentalSub')}</p></div>`};
go=function(tab){if(state.service==='market'){state.tab=tab==='trips'?'orders':tab;drawHeader();drawTabs();window.scrollTo(0,0);renderMarket();return}rentalGo(tab);drawHeader();const q=$('#q');if(q)q.placeholder=state.lang==='ru'?'Город, район или название':'Місто, район або назва'};
card=function(l,i){const p=priceOf(l),d=p*(100-l.disc)/100;return `<article class="card" style="--i:${Math.min(i,8)}" data-open="${l.id}"><div class="phw"><div class="ph">${l.np?imgs(l,4):`<div class="none">${icon('home')}</div>`}</div><div class="bd">${l.top?`<span class="tag top">${state.lang==='ru'?'В центре внимания':'У центрі уваги'}</span>`:''}${l.ver?`<span class="tag ok">${state.lang==='ru'?'Проверен':'Перевірено'}</span>`:''}</div><button class="ht ${l.fav?'active':''}" data-a="fav" data-id="${l.id}" aria-label="${t('favorites')}">${icon('heart')}</button><button class="cmpb ${CMPL.includes(l.id)?'on':''}" data-a="cmp" data-id="${l.id}" aria-label="${state.lang==='ru'?'Сравнить':'Порівняти'}">⇄</button></div><div class="in"><div class="trow"><h2 class="t">${esc(l.title)}</h2>${l.rn?`<span class="rt">★ ${esc(l.rating)}</span>`:''}</div><div class="s">${esc(l.city)} · ${esc(l.district)} · ${l.rooms} ${state.lang==='ru'?'комн.':'кімн.'}</div><div class="p">${l.disc?`<s>${money(p)}</s>`:''}${money(d)} <small>/ ${F.month&&l.pm?(state.lang==='ru'?'месяц':'місяць'):(state.lang==='ru'?'ночь':'ніч')}</small></div></div></article>`};
function switchService(service){if(!['rental','market'].includes(service))return;state.service=service;ls.set('dm_service',service);state.tab='search';while(SH.length)closeSheet();go('search');const cb=$('#cmpbar');if(cb&&service==='market')cb.classList.remove('on')}
function empty(title,sub,action=''){return `<div class="empty"><div class="mk-emptyicon">${icon('search')}</div><h2 style="font-size:21px;color:var(--tx);margin-bottom:8px">${title}</h2><p>${sub||''}</p>${action}</div>`}
function login(){sheet(`<div class="pad mk-form">${empty(t('login'),t('loginSub'),`<br><button class="cta" data-a="inbot">${t('login')}</button>`)}</div>`,'plain')}
async function auth(){if(!ME.tg){login();return false}return await needUser()}
function page(title,sub=''){return `<div class="dm-hero"><h1 class="dm-title small">${title}</h1>${sub?`<p class="dm-sub">${sub}</p>`:''}</div>`}
function safety(){sheet(`<div class="pad mk-form mk-safe"><h1 class="h1">${t('safeTitle')}</h1><div class="box warn">${icon('shield')} ${t('safeInfo')}</div><h2 class="h2">${t('safe')}</h2><p>${t('safeLinks')}</p><p style="margin-top:18px">${t('safeChat')}</p><p style="margin-top:18px">${t('safeProblem')}</p></div>`,'plain')}
copy.uk.clothes=copy.uk.clothing;copy.ru.clothes=copy.ru.clothing;copy.uk.kids=copy.uk.children;copy.ru.kids=copy.ru.children;copy.uk.transport='Транспорт';copy.ru.transport='Транспорт';copy.uk.like_new='Як нове';copy.ru.like_new='Как новое';copy.uk.for_parts='На запчастини';copy.ru.for_parts='На запчасти';
const categories=[['','all'],['furniture','furniture'],['electronics','electronics'],['clothes','clothing'],['kids','children'],['sport','sport'],['home','home'],['transport','transport'],['other','other']];
const photo=(l,i=0)=>`/api/market/photo/${Number(l.id)}/${i}`;
function marketCard(l){return `<article class="mk-card"><div class="mk-cover"><button class="mk-open" data-mid="${Number(l.id)}" aria-label="${esc(l.title)}">${l.photos?.length?`<img src="${photo(l)}" loading="lazy" alt="${esc(l.title)}">`:`<span class="mk-blank">${icon('photo')}</span>`}</button><button class="ht ${l.favorite?'active':''}" data-mfav="${l.id}" aria-label="${t('favorites')}" aria-pressed="${!!l.favorite}">${icon('heart')}</button></div><div class="mk-price">${money(l.price)}</div>${l.mine&&l.status!=='active'?`<span class="mk-status">${({uk:{pending:'На перевірці',blocked:'Заблоковано',reserved:'Зарезервовано',sold:'Продано',deleted:'Знято'},ru:{pending:'На проверке',blocked:'Заблокировано',reserved:'Зарезервировано',sold:'Продано',deleted:'Снято'}})[state.lang][l.status]||esc(l.status)}</span>`:''}<button class="mk-name" data-mid="${l.id}">${esc(l.title)}</button><div class="mk-place">${icon('pin')}${esc(l.city)}</div><button class="mk-seller" data-mseller="${l.seller_id}"><span class="mk-avatar">${esc((l.seller_name||'?').slice(0,1))}</span>${esc(l.seller_name||t('seller'))}</button></article>`}
async function renderMarket(){const tab=state.tab;if(['search','fav','mine'].includes(tab))return searchMarket();if(tab==='chats')return chatList();if(tab==='orders')return orderList();if(tab==='me')return marketProfile()}
async function searchMarket(){const view=$('#view'),fav=state.tab==='fav',mine=state.tab==='mine';const seq=++state.sequence;view.innerHTML=`<section class="mk-page">${fav?page(t('favorites')):mine?page(t('mine')):`<div class="dm-hero"><h1 class="dm-title">${t('marketTitle').replace('\n','<br>')}</h1><p class="dm-sub">${t('marketSub')}</p><div class="mk-toolbar"><div class="si">${icon('search')}<input id="mk-query" type="search" enterkeyhint="search" placeholder="${t('query')}" value="${esc(state.q)}"></div><button class="dm-ib" data-dm="filters" aria-label="${t('filters')}">${icon('filter')}</button></div><div class="chips mk-cats">${categories.map(([k,l])=>`<button class="c ${state.category===k?'on':''}" data-mcat="${k}">${t(l)}</button>`).join('')}</div></div>`}${!fav&&!mine?`<button class="mk-note" data-dm="safe">${icon('shield')}<span>${t('safeShort')}</span></button>`:''}<div id="mk-count" class="mk-count"></div><div id="mk-list" class="mk-grid">${Array(4).fill('<div class="mk-skeleton"></div>').join('')}</div></section>`;
 const q=$('#mk-query');if(q){let timer;q.oninput=()=>{state.q=q.value;clearTimeout(timer);timer=setTimeout(()=>loadMarket(seq,fav,mine),330)};q.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);q.blur();loadMarket(seq,fav,mine)}}}await loadMarket(seq,fav,mine)}
let marketRequest=0;
async function loadMarket(seq,fav,mine){const ticket=++marketRequest;if(fav||mine)if(!ME.tg){$('#mk-list').style.display='block';$('#mk-list').innerHTML=empty(t('login'),t('loginSub'),`<br><button class="cta" data-a="inbot">${t('login')}</button>`);return}try{const p=new URLSearchParams({q:state.q,category:state.category,city:state.city,min:state.min,max:state.max});if(mine)p.set('mine','1');const r=await request(fav?'/favorites':'/listings?'+p);if(ticket!==marketRequest||seq!==state.sequence||state.service!=='market')return;state.items=items(r);const target=$('#mk-list');if(!target)return;$('#mk-count').textContent=state.items.length?`${state.items.length} ${t('found')}`:'';target.style.display=state.items.length?'grid':'block';target.innerHTML=state.items.length?state.items.map(marketCard).join(''):empty(fav?t('emptyFav'):t('empty'),fav?t('favSub'):t('emptySub'),mine?`<br><button class="cta" data-dm="add">${t('add')}</button>`:'')}catch(e){if(ticket!==marketRequest||seq!==state.sequence||state.service!=='market')return;const target=$('#mk-list');if(target){target.style.display='block';target.innerHTML=empty(t('error'),esc(e.message),`<br><button class="cta g2" data-dm="refresh">${t('retry')}</button>`)}}}
function filters(){const s=sheet(`<form class="pad mk-form" id="mk-filters"><h1 class="h1">${t('filters')}</h1><label class="fl" for="mf-city">${t('city')}</label><input id="mf-city" maxlength="80" value="${esc(state.city)}"><label class="fl">${t('price')}, грн</label><div class="mk-fieldrow"><input aria-label="${t('from')}" id="mf-min" type="number" min="0" placeholder="${t('from')}" value="${esc(state.min)}"><input aria-label="${t('to')}" id="mf-max" type="number" min="0" placeholder="${t('to')}" value="${esc(state.max)}"></div><div class="bar"><button class="cta g2" type="button" id="mf-reset">${t('reset')}</button><button class="cta" type="submit">${t('apply')}</button></div></form>`);s.querySelector('form').onsubmit=e=>{e.preventDefault();state.city=$('#mf-city').value.trim();state.min=$('#mf-min').value;state.max=$('#mf-max').value;closeSheet(s);searchMarket()};$('#mf-reset').onclick=()=>{state.city=state.min=state.max='';closeSheet(s);searchMarket()}}
