async function chatList(){const seq=++state.sequence;$('#view').innerHTML=page(t('chats'))+'<div class="pad" id="mk-chatlist"><div class="sk" style="height:150px"></div></div>';if(!ME.tg){$('#mk-chatlist').innerHTML=empty(t('login'),t('loginSub'));return}try{const list=items(await request('/chats'));if(seq!==state.sequence)return;$('#mk-chatlist').innerHTML=list.length?list.map(c=>`<button class="mk-thread" data-mchat="${c.id}"><span class="mk-avatar large">${esc((c.peer_name||c.name||'?').slice(0,1))}</span><span class="grow"><b>${esc(c.peer_name||c.name||t('seller'))}</b><p>${esc(c.listing_title||c.title||'')}</p><p>${esc(c.last_message||c.last_body||'')}</p></span>${icon('chevron')}</button>`).join(''):empty(t('noChats'),'')}catch(e){$('#mk-chatlist').innerHTML=empty(t('error'),esc(e.message))}}
