async function chat(id){if(!await auth())return;const s=sheet(`<div class="mk-chat-top"><div class="mk-chat-title">${t('chats')}</div><div class="mk-help">${t('chatHint')}</div></div><div class="mk-chat-messages" id="mc-msgs"></div><form class="mk-compose"><textarea id="mc-body" placeholder="${t('message')}" aria-label="${t('message')}" maxlength="2000" rows="1" required></textarea><button type="submit" aria-label="${t('send')}">${icon('send')}</button></form>`,'plain');let busy=false,previous='';const msgs=s.querySelector('#mc-msgs'),form=s.querySelector('form');async function refresh(){if(busy||!document.body.contains(s)||document.hidden)return;busy=true;try{const r=await request('/chats/'+id+'/messages');const list=items(r);const signature=JSON.stringify(list.map(m=>m.id));if(signature!==previous){const nearBottom=s.scrollHeight-s.scrollTop-s.clientHeight<150;previous=signature;msgs.innerHTML=list.map(m=>`<div class="m ${Number(m.sender)===Number(ME.id)?'me':''}">${esc(m.body)}<small>${when(m.created)}</small></div>`).join('');if(nearBottom||!s.dataset.loaded){s.scrollTop=s.scrollHeight;s.dataset.loaded='1'}}}catch(e){if(!s.dataset.loaded){msgs.innerHTML=`<div class="box">${esc(e.message)}</div>`;s.dataset.loaded='1'}}finally{busy=false}}
 form.onsubmit=async e=>{e.preventDefault();const field=s.querySelector('#mc-body'),body=field.value.trim();if(!body)return;const b=form.querySelector('button');b.disabled=true;try{await request('/chats/'+id+'/messages','POST',{body});field.value='';await refresh();s.scrollTop=s.scrollHeight}catch(x){onError(x)}finally{b.disabled=false}};await refresh();const timer=setInterval(()=>{if(!document.body.contains(s)){clearInterval(timer);return}refresh()},5000)}
async function orderList(){const seq=++state.sequence;$('#view').innerHTML=page(t('orders'))+'<div class="pad" id="mk-orders"><div class="sk" style="height:140px"></div></div>';if(!ME.tg){$('#mk-orders').innerHTML=empty(t('login'),t('loginSub'));return}try{const list=items(await request('/orders'));if(seq!==state.sequence)return;$('#mk-orders').innerHTML=list.length?list.map(orderCard).join(''):empty(t('noOrders'),'');$('#mk-orders').querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderDetail(list.find(x=>Number(x.id)===Number(b.dataset.order))))}catch(e){$('#mk-orders').innerHTML=empty(t('error'),esc(e.message))}}
function orderCard(o){const isSeller=Number(o.seller_id)===Number(ME.id);return `<article class="mk-order"><div class="row sp"><span class="mk-help">${t(isSeller?'selling':'purchases')} · #${o.id}</span><span class="mk-help">${when(o.created)}</span></div><h2 style="font-size:18px;margin-top:10px">${esc(o.listing_title||o.title||t('orderNumber'))}</h2><div class="mk-price">${money(o.price||o.total)}</div><span class="mk-status">${t(o.status)}</span>${o.ttn?`<div class="s">${t('ttn')}: ${esc(o.ttn)}</div>`:''}<button class="cta g2 mk-full" data-order="${o.id}" style="margin-top:10px">${t('orders')} ${icon('arrow')}</button></article>`}
function orderDetail(o){if(!o)return;const own=Number(o.seller_id)===Number(ME.id),r=o.recipient||{},canCancel=['pending','accepted'].includes(o.status);const s=sheet(`<div class="pad mk-form"><h1 class="h1">${t('orderNumber')} #${o.id}</h1><span class="mk-status">${t(o.status)}</span><h2 class="h2">${esc(o.listing_title||o.title||'')}</h2><div class="p">${money(o.price||o.total)}</div>${o.items?.length>1?`<div class="dm-order-items"><h3>${L('У цьому замовленні','В этом заказе')}</h3>${o.items.map(x=>`<div class="row sp"><span>${esc(x.title)}</span><b>${money(x.price)}</b></div>`).join('')}<p class="mk-help">${L('Одна спільна посилка від цього продавця.','Одна общая посылка от этого продавца.')}</p></div>`:''}${shippingStateMarkup(o)}<div class="box"><b>${t(o.carrier==='nova'?'nova':o.carrier==='ukr'?'ukr':'pickup')}</b><p>${esc(r.name||'')}<br>${esc(r.phone||'')}<br>${esc(r.city||'')}<br>${esc(r.branch||'')}</p></div><div class="box">${t(o.payment==='pickup'?'pickupPay':'cod')}<p class="mk-help">${t('paymentNote')}</p></div>${o.ttn?`<label class="fl">${t('ttn')}</label><div class="row"><input value="${esc(o.ttn)}" readonly aria-label="${t('ttn')}"><button class="cta g2" id="od-copy">${t('copy')}</button></div><button class="cta g2 mk-full" id="od-track" style="margin-top:10px">${t('track')}</button><div id="od-tracking" role="status"></div>`:''}<div class="mk-actions">${own&&o.status==='pending'?`<button class="cta" data-status="accepted">${t('accept')}</button>`:''}${own&&o.status==='accepted'&&o.carrier!=='pickup'?`<button class="cta" id="od-ship">${t('shippedButton')}</button>`:''}${!own&&(o.status==='shipped'||(o.status==='accepted'&&o.carrier==='pickup'))?`<button class="cta" data-status="completed">${t('complete')}</button>`:''}${canCancel?`<button class="cta g2" data-status="cancelled">${t('cancel')}</button>`:''}${!own&&o.status==='completed'&&!o.reviewed?`<button class="cta" id="od-review">${t('review')}</button>`:''}</div><button class="cta g2 mk-full" id="od-chat">${t('write')}</button><p class="mk-error" id="od-error" role="alert"></p></div>`,'plain');
 s.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{if(b.dataset.status==='cancelled'&&!await confirm(t('cancelConfirm')))return;b.disabled=true;try{await request('/orders/'+o.id,'PATCH',{status:b.dataset.status});closeSheet(s);orderList()}catch(x){s.querySelector('#od-error').textContent=x.message;b.disabled=false}});
 const ch=s.querySelector('#od-chat');ch.onclick=()=>startChat(o.listing_id);const cp=s.querySelector('#od-copy');if(cp)cp.onclick=()=>navigator.clipboard.writeText(o.ttn).then(()=>toast(t('copied'))).catch(onError);const tr=s.querySelector('#od-track');if(tr)tr.onclick=async()=>{tr.disabled=true;try{const r=await request('/delivery/track?order_id='+o.id);s.querySelector('#od-tracking').textContent=item(r).Status||item(r).status||JSON.stringify(r)}catch(x){s.querySelector('#od-tracking').textContent=x.message}finally{tr.disabled=false}};const ship=s.querySelector('#od-ship');if(ship)ship.onclick=()=>shippingOrder(o,s);const rev=s.querySelector('#od-review');if(rev)rev.onclick=()=>reviewOrder(o,s)}
function shippingOrder(o,parent){const s=sheet(`<form class="pad mk-form"><h1 class="h1">${t('delivery')}</h1><p class="mk-help">${t('shippingHelp')}</p>${o.carrier==='nova'&&!o.ttn?`<div class="box"><b>${t('parcel')}</b><div class="mk-fieldrow">${['weight','length','width','height'].map(k=>`<div><label class="fl" for="os-${k}">${t(k)}</label><input id="os-${k}" type="number" min="0.01" max="1000" step="0.01" value="${o.items?.length>1?'':Number(o.parcel?.[k])||''}"></div>`).join('')}</div><button class="cta mk-full" type="button" id="os-auto" style="margin-top:15px">${state.lang==='ru'?'Создать накладную':'Створити накладну'}</button></div>`:''}<label class="fl" for="os-ttn">${t('ttn')}</label><input id="os-ttn" value="${esc(o.ttn||'')}" inputmode="numeric" pattern="[0-9]{8,20}" required minlength="8" maxlength="20" placeholder="${state.lang==='ru'?'Или добавьте созданную накладную':'Або додайте створену накладну'}">${o.carrier==='nova'?`<label class="mk-check"><input type="checkbox" id="os-checked"><span>${state.lang==='ru'?'Я проверил(а) эту накладную в своём кабинете Новой почты':'Я перевірив(ла) цю накладну у своєму кабінеті Нової пошти'}</span></label>`:''}<p class="mk-error" id="os-error" role="alert"></p><button class="cta mk-full" type="submit" style="margin-top:20px">${t('shippedButton')}</button></form>`,'plain');const el=id=>s.querySelector('#'+id);const auto=el('os-auto');if(auto)auto.onclick=async()=>{auto.disabled=true;try{const parcel={};for(const k of ['weight','length','width','height'])parcel[k]=Number(el('os-'+k).value);const r=await request('/delivery/waybill','POST',{order_id:o.id,parcel});const d=r.delivery||item(r);el('os-ttn').value=d.ttn||item(r).ttn||'';toast(t('saved'))}catch(e){el('os-error').textContent=e.message}finally{auto.disabled=false}};s.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=s.querySelector('button[type=submit]');b.disabled=true;try{const fresh=item(await request('/orders/'+o.id));if(fresh.shipping_state==='reconciliation_required'){if(!el('os-checked')?.checked)throw new Error(state.lang==='ru'?'Проверьте накладную в кабинете и подтвердите это':'Перевірте накладну в кабінеті та підтвердьте це');await request('/delivery/reconcile','POST',{order_id:o.id,ttn:el('os-ttn').value.trim(),confirmed_in_carrier_account:true})}await request('/orders/'+o.id,'PATCH',{status:'shipped',ttn:el('os-ttn').value.trim()});closeSheet(s);closeSheet(parent);orderList()}catch(x){el('os-error').textContent=x.message;b.disabled=false}}}
function reviewOrder(o,parent){const s=sheet(`<form class="pad mk-form"><h1 class="h1">${t('review')}</h1><label class="fl" for="or-rating">${t('rating')}</label><select id="or-rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)}</option>`).join('')}</select><label class="fl" for="or-body">${t('reviewText')}</label><textarea id="or-body" maxlength="2000"></textarea><button class="cta mk-full" style="margin-top:20px" type="submit">${t('send')}</button><p class="mk-error" id="or-error" role="alert"></p></form>`,'plain');s.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=s.querySelector('button[type=submit]');b.disabled=true;try{await request('/orders/'+o.id+'/review','POST',{rating:Number(s.querySelector('#or-rating').value),text:s.querySelector('#or-body').value});closeSheet(s);closeSheet(parent);toast(t('reviewThanks'));orderList()}catch(x){s.querySelector('#or-error').textContent=x.message;b.disabled=false}}}
