 try{saved=item(await request('/delivery/settings'))}catch(e){onError(e)}
 const sender=saved.sender||{};let cityRef=sender.city_ref||'',warehouseRef=sender.warehouse_ref||'',cities=[],branches=[],cityTimer,lookup=0;
 const s=sheet(`<form class="pad mk-form"><div class="dm-page-kicker">${icon('box')} ${L('ПРОСТА ДОСТАВКА','ПРОСТАЯ ДОСТАВКА')}</div><h1 class="h1">${L('Звідки ви відправляєте?','Откуда вы отправляете?')}</h1><p class="dm-sub">${L('Додайте звичайні дані відправника. Вони потрібні для оформлення доставки покупцю.','Добавьте обычные данные отправителя. Они нужны для оформления доставки покупателю.')}</p><label class="fl" for="ds-name">${L('Прізвище та ім’я','Фамилия и имя')}</label><input id="ds-name" autocomplete="name" required minlength="3" maxlength="100" value="${esc(sender.name||'')}"><label class="fl" for="ds-phone">${t('senderPhone')}</label><input type="tel" autocomplete="tel" id="ds-phone" required value="${esc(sender.phone||'')}" placeholder="+380…"><label class="fl" for="ds-city">${t('senderCity')}</label><input id="ds-city" autocomplete="off" placeholder="${t('findCity')}" value="${esc(sender.city_name||'')}"><select id="ds-cities" aria-label="${t('selectCity')}" style="margin-top:8px"><option value="${esc(cityRef)}">${cityRef?esc(sender.city_name||t('saved')):t('selectCity')}</option></select><label class="fl" for="ds-warehouse">${t('senderWarehouse')}</label><select id="ds-warehouse" required><option value="${esc(warehouseRef)}">${warehouseRef?esc(sender.warehouse_name||t('saved')):t('selectBranch')}</option></select><div class="dm-delivery-explain">${badgeIcon('shield','mint')}<p>${L('Після підтвердження замовлення сервіс спробує оформити накладну за збереженими даними. Якщо автоматичне оформлення ще недоступне, додайте справжню накладну з застосунку Нової пошти.','После подтверждения заказа сервис попробует оформить накладную по сохранённым данным. Если автоматическое оформление ещё недоступно, добавьте настоящую накладную из приложения Новой почты.')}</p></div><p class="mk-error" id="ds-error" role="alert"></p><button class="cta mk-full" type="submit" style="margin-top:20px">${L('Зберегти дані відправника','Сохранить данные отправителя')}</button></form>`,'plain');
 const el=id=>s.querySelector('#'+id);
 el('ds-city').oninput=()=>{cityRef=warehouseRef='';clearTimeout(cityTimer);const ticket=++lookup;if(el('ds-city').value.trim().length<2)return;cityTimer=setTimeout(async()=>{try{cities=items(await request('/delivery/cities?'+new URLSearchParams({q:el('ds-city').value.trim()})));if(ticket!==lookup)return;el('ds-cities').innerHTML=`<option value="">${t('selectCity')}</option>`+cities.map(c=>`<option value="${esc(c.ref||c.Ref)}">${esc(c.name||c.Description)}</option>`).join('');el('ds-error').textContent=''}catch(e){el('ds-error').textContent=L('Довідник доставки тимчасово недоступний. Спробуйте пізніше.','Справочник доставки временно недоступен. Попробуйте позже.')}},350)};
 el('ds-cities').onchange=async()=>{cityRef=el('ds-cities').value;warehouseRef='';const c=cities.find(x=>(x.ref||x.Ref)===cityRef);if(c)el('ds-city').value=c.name||c.Description;try{branches=items(await request('/delivery/warehouses?'+new URLSearchParams({city_ref:cityRef})));el('ds-warehouse').innerHTML=`<option value="">${t('selectBranch')}</option>`+branches.map(b=>`<option value="${esc(b.ref||b.Ref)}">${esc(b.name||b.Description)}</option>`).join('')}catch(e){el('ds-error').textContent=e.message}};
