 const d=document.createElement('aside');d.className='dm-sponsored';d.innerHTML=`<button class="dm-sponsored-close" aria-label="${t('close')}">${icon('close')}</button><span class="dm-ad-label">${L('Реклама','Реклама')}</span><button class="dm-sponsored-body"><div><b>${esc(banner.title)}</b><p>${esc(banner.body||'')}</p><span>${L('Дізнатися більше','Узнать больше')} ${icon('arrow')}</span></div>${banner.image_url&&/^https:\/\//i.test(banner.image_url)?`<img alt="" loading="lazy" src="${esc(banner.image_url)}" referrerpolicy="no-referrer">`:''}</button>`;target.before(d);
